const config = $input.first().json;
const now = new Date();
const weekEnd = new Date(now);
const weekStart = new Date(now);
weekStart.setUTCDate(weekStart.getUTCDate() - 7);

return [{
  json: {
    ...config,
    weekStartIso: weekStart.toISOString(),
    weekEndIso: weekEnd.toISOString(),
    weekStartDate: weekStart.toISOString().slice(0, 10),
    weekEndDate: weekEnd.toISOString().slice(0, 10),
    repoSlug: `${config.githubOwner}/${config.githubRepo}`
  }
}];

const config = $('Compute Week Window').first().json;

return [{
  json: {
    ...config,
    commits: [
      { sha: '4f3a9b1', commit: { message: 'Add structured PR review agent', author: { name: 'ScryUser' } }, html_url: 'https://github.com/example/repo/commit/4f3a9b1' },
      { sha: '7be6812', commit: { message: 'Add Next.js SQLite CLAUDE template', author: { name: 'ScryUser' } }, html_url: 'https://github.com/example/repo/commit/7be6812' }
    ],
    closedIssues: [
      { number: 41, title: 'Document weekly summary setup', html_url: 'https://github.com/example/repo/issues/41', closed_at: config.weekEndIso }
    ],
    mergedPullRequests: [
      { number: 82, title: 'Ship reviewer workflow docs', html_url: 'https://github.com/example/repo/pull/82', closed_at: config.weekEndIso }
    ]
  }
}];

const config = $('Compute Week Window').first().json;

function asArray(value) {
  if (Array.isArray(value)) return value;
  if (Array.isArray(value?.items)) return value.items;
  if (Array.isArray(value?.body)) return value.body;
  if (Array.isArray(value?.json)) return value.json;
  return [];
}

let commits = [];
let closedIssues = [];
let mergedPullRequests = [];

if (config.dryRun) {
  const sample = $('Build Sample Activity').first().json;
  commits = sample.commits;
  closedIssues = sample.closedIssues;
  mergedPullRequests = sample.mergedPullRequests;
} else {
  commits = asArray($('Fetch Commits').first().json);
  closedIssues = asArray($('Fetch Closed Issues').first().json);
  mergedPullRequests = asArray($('Fetch Merged Pull Requests').first().json);
}

const commitLines = commits.slice(0, 30).map((commit) => {
  const sha = (commit.sha || '').slice(0, 7);
  const message = (commit.commit?.message || commit.message || '').split('\n')[0];
  const author = commit.commit?.author?.name || commit.author?.login || 'unknown';
  return `- ${sha} ${message} (${author})`;
});

const issueLines = closedIssues.slice(0, 30).map((issue) => `- #${issue.number} ${issue.title}`);
const prLines = mergedPullRequests.slice(0, 30).map((pr) => `- #${pr.number} ${pr.title}`);

const languageInstruction = config.language === 'FR'
  ? 'Write the final weekly summary in French.'
  : 'Write the final weekly summary in English.';

const prompt = `You are preparing a weekly developer activity summary for ${config.repoSlug}.\n\n${languageInstruction}\n\nCover the period ${config.weekStartDate} through ${config.weekEndDate}. Write a concise narrative summary suitable for posting to a team Slack or Discord channel. Include:\n- Overall theme of the week\n- Notable commits\n- Closed issues\n- Merged pull requests\n- Suggested next focus\n\nCommits:\n${commitLines.join('\n') || '- None found'}\n\nClosed issues:\n${issueLines.join('\n') || '- None found'}\n\nMerged pull requests:\n${prLines.join('\n') || '- None found'}\n`;

return [{
  json: {
    ...config,
    activityCounts: {
      commits: commits.length,
      closedIssues: closedIssues.length,
      mergedPullRequests: mergedPullRequests.length
    },
    prompt
  }
}];

const item = $input.first().json;
const summaryMarkdown = `## Weekly Dev Summary: ${item.repoSlug}

This dry-run summary confirms the workflow path can collect activity, prepare a Claude-ready prompt, and format a delivery payload without exposing external credentials. The sample week includes ${item.activityCounts.commits} commits, ${item.activityCounts.closedIssues} closed issue, and ${item.activityCounts.mergedPullRequests} merged pull request.

### Highlights
- The team shipped reviewer and project-template improvements.
- Documentation work reduced setup friction.
- The next focus should be validating live webhook delivery with production credentials.

### Confidence
High for workflow wiring; live Claude quality depends on the configured Anthropic API key and repository activity volume.`;

return [{
  json: {
    ...item,
    summaryMarkdown,
    claudeModel: 'dry-run-mock-for-local-validation'
  }
}];

const config = $('Compute Week Window').first().json;
const input = $input.first().json;

function extractClaudeText(value) {
  if (value.summaryMarkdown) return value.summaryMarkdown;
  const content = value.content || value.body?.content || [];
  if (Array.isArray(content)) {
    return content.map((part) => part.text || '').filter(Boolean).join('\n\n');
  }
  return value.text || 'No summary returned by Claude.';
}

const summaryMarkdown = extractClaudeText(input);
const title = `Weekly dev summary for ${config.repoSlug} (${config.weekStartDate} to ${config.weekEndDate})`;
const provider = config.destinationProvider === 'discord' ? 'discord' : 'slack';
const deliveryBody = provider === 'discord'
  ? { content: `**${title}**\n\n${summaryMarkdown}`.slice(0, 1900) }
  : { text: `*${title}*\n\n${summaryMarkdown}` };

return [{
  json: {
    ...config,
    title,
    provider,
    summaryMarkdown,
    deliveryBody,
    deliverySkipped: config.dryRun || !config.destinationWebhookUrl
  }
}];

const item = $input.first().json;
return [{
  json: {
    status: 'success',
    dryRun: item.dryRun,
    delivered: false,
    reason: item.dryRun ? 'Dry run enabled; webhook delivery intentionally skipped.' : 'DESTINATION_WEBHOOK_URL is not configured.',
    title: item.title,
    provider: item.provider,
    summaryPreview: item.summaryMarkdown.slice(0, 500)
  }
}];
